    # 以 O_DIRECTORY 调用 os.open，那些目录 fd 必须放行，回滚才能生效。
    if flags & os.O_EXCL:
        calls["n"] += 1
        if calls["n"] > fail_after_files:
            raise OSError("injected open failure")
